import { useEffect, useRef, useState } from 'react';

import ActionsStep from './ActionsStep';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Divider from '@mui/material/Divider';
import DynamicStepper from './components/DynamicStepper';
import FinishStep from './FinishStep';
import { FormData } from '@/types';
import GameModeStep from './GameModeStep';
import LocalPlayersStep from './LocalPlayersStep';
import PlayerTopologyStep from './PlayerTopologyStep';
import RoomStep from './RoomStep';
import { Settings } from '@/types/Settings';
import { Trans, useTranslation } from 'react-i18next';
import { deriveParticipationContentMode, isPublicRoom, usesSoloActions } from '@/helpers/strings';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { cleanFormData } from '@/services/gameSettingsOrchestrator';
import { useLocalPlayers } from '@/hooks/useLocalPlayers';
import { useSettings } from '@/stores/settingsStore';
import useSettingsToFormData from '@/hooks/useSettingsToFormData';
import useUnifiedActionList from '@/hooks/useUnifiedActionList';
import { useWizardAnalytics } from '@/hooks/useWizardAnalytics';
import { nextStepAfter, prevStepBefore, stepsFor } from './wizardFlow';

interface GameSettingsWizardProps {
  close?: () => void;
}

export default function GameSettingsWizard({ close }: GameSettingsWizardProps) {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { id: room } = useParams<{ id: string }>();
  const [searchParams] = useSearchParams();
  const joinAtStep = searchParams.get('step') === '2';
  // Set by goToAdvanced before navigating away, so returning from Advanced
  // Settings resumes at the step the user left, instead of restarting at 1.
  const resumeStepParam = Number(searchParams.get('resumeStep'));
  const resumeStep =
    Number.isInteger(resumeStepParam) && resumeStepParam >= 1 && resumeStepParam <= 5
      ? resumeStepParam
      : undefined;
  const [step, setStep] = useState<number>(resumeStep ?? (joinAtStep ? 2 : 1));

  // Forces useUnifiedActionList to reload (e.g. after a pack import). Seeding
  // needs no reload hack: getGroupsWithTiles/getTileCountsByGroup await
  // content readiness, so the first read already resolves post-seeding.
  const [reloadToggle, setReloadToggle] = useState(false);

  const overrideSettings: Record<string, any> = {
    room: room || 'PUBLIC',
    ...(joinAtStep && { gameMode: 'online' }),
  };

  const [formData, setFormData] = useSettingsToFormData<FormData & Partial<Settings>>(
    {
      gameMode: 'solo',
      roomRealtime: true,
      actions: [],
      consumption: [],
      role: 'sub',
      gender: 'non-binary',
      boardUpdated: false,
      room: room || 'PUBLIC',
      selectedActions: {},
    },
    overrideSettings
  );

  const isSoloPlay = usesSoloActions(formData.gameMode, formData.soloPlay);
  const contentGameMode = deriveParticipationContentMode(formData.gameMode, formData.soloPlay);

  // Clear selected actions when the play context changes (different content becomes available)
  const prevContentGameModeRef = useRef(contentGameMode);
  const prevIsSoloPlayRef = useRef(isSoloPlay);
  const prevIsNakedRef = useRef(formData.isNaked);
  const isFirstRenderRef = useRef(true);

  useEffect(() => {
    if (isFirstRenderRef.current) {
      isFirstRenderRef.current = false;
      return;
    }
    const modeChanged =
      prevContentGameModeRef.current !== contentGameMode ||
      prevIsSoloPlayRef.current !== isSoloPlay ||
      (contentGameMode === 'local' && prevIsNakedRef.current !== formData.isNaked);

    if (modeChanged && Object.keys(formData.selectedActions || {}).length > 0) {
      setFormData((prev) => ({ ...prev, selectedActions: {} }));
    }
    prevContentGameModeRef.current = contentGameMode;
    prevIsSoloPlayRef.current = isSoloPlay;
    prevIsNakedRef.current = formData.isNaked;
  }, [contentGameMode, isSoloPlay, formData.isNaked]);

  const { actionsList, isLoading: isActionsLoading } = useUnifiedActionList(
    contentGameMode,
    true,
    reloadToggle // Forces reload after pack imports
  );

  // Analytics tracking for wizard funnel
  const { trackScreenView, markCompleted } = useWizardAnalytics({
    gameMode: formData.gameMode,
    isPublicRoom: isPublicRoom(formData.room || 'PUBLIC'),
  });

  // One screen-view per step entered (including the initial screen)
  useEffect(() => {
    if (step > 0) {
      trackScreenView(step);
    }
  }, [step, trackScreenView]);

  // Solo skips wizard step 2 entirely — nextStep/prevStep consult the flow
  // graph for this topology instead of adding/subtracting a count.
  const nextStep = (): void => {
    setStep((current) => nextStepAfter(formData.gameMode, current));
  };

  const handleStepClick = (targetStep: number): void => {
    setStep(targetStep);
  };

  const prevStep = (): void => {
    setStep((current) => prevStepBefore(formData.gameMode, current));
  };

  const [, updateSettings] = useSettings();
  const { createLocalSession } = useLocalPlayers();

  const goToAdvanced = async (): Promise<void> => {
    // Advanced re-derives its form data from persisted settings on mount; without
    // this merge, any picks made here but not yet submitted (no Finish step reached)
    // are silently discarded.
    updateSettings(cleanFormData(formData as Settings));

    // Local players live in their own session store, not settings — Advanced's
    // roster reads from there, so a Shared Device pick staged here (Next
    // clicked past LocalPlayersStep) also needs persisting or it arrives empty.
    const typedFormData = formData as any;
    if (
      typedFormData.hasLocalPlayers &&
      typedFormData.localPlayersData &&
      typedFormData.localPlayerSessionSettings
    ) {
      try {
        await createLocalSession(
          (formData.room || room || 'PUBLIC').toUpperCase(),
          typedFormData.localPlayersData,
          typedFormData.localPlayerSessionSettings
        );
      } catch {
        // Non-blocking — same tolerance as the real submit path
      }
    }

    // resumeStep round-trips through Advanced's own back button so returning
    // here lands back on this exact step instead of restarting the wizard.
    navigate(`/${(formData.room || room || 'PUBLIC').toUpperCase()}/settings?resumeStep=${step}`);
  };

  const renderStep = (): JSX.Element | null => {
    switch (step) {
      case 1:
        return (
          <PlayerTopologyStep formData={formData} setFormData={setFormData} nextStep={nextStep} />
        );
      case 2:
        if (formData.gameMode === 'online') {
          return (
            <RoomStep
              formData={formData}
              setFormData={setFormData}
              nextStep={nextStep}
              prevStep={prevStep}
            />
          );
        }

        if (formData.gameMode === 'local') {
          return (
            <LocalPlayersStep
              formData={formData}
              setFormData={setFormData}
              nextStep={nextStep}
              prevStep={prevStep}
            />
          );
        }

        return null;
      case 3:
        return (
          <GameModeStep
            formData={formData}
            setFormData={setFormData}
            nextStep={nextStep}
            prevStep={prevStep}
          />
        );
      case 4:
        return (
          <ActionsStep
            formData={formData}
            setFormData={setFormData}
            nextStep={nextStep}
            prevStep={prevStep}
            actionsList={actionsList}
            isActionsLoading={isActionsLoading}
            onActionsReload={() => setReloadToggle((prev) => !prev)}
          />
        );
      case 5:
        return (
          <FinishStep
            formData={formData}
            setFormData={setFormData}
            prevStep={prevStep}
            actionsList={actionsList}
            close={close}
            onCompleted={markCompleted}
          />
        );
      default:
        return null;
    }
  };

  const flowSteps = stepsFor(formData.gameMode);
  const stepperSteps = flowSteps.map((entry) => ({
    label: String(t(entry.labelKey, entry.labelFallback)),
    wizardStep: entry.wizardStep,
  }));
  const activeStep = flowSteps.findIndex((entry) => entry.wizardStep === step);

  return (
    <Box>
      <Box sx={{ width: '100%', mt: 2, mb: 4 }}>
        <DynamicStepper
          steps={stepperSteps}
          activeStep={activeStep}
          onStepClick={handleStepClick}
        />
      </Box>
      {renderStep()}

      <Divider sx={{ mt: 3 }} />

      <Button onClick={goToAdvanced}>
        <Trans i18nKey="advancedSetup" />
      </Button>
    </Box>
  );
}
